<script setup lang="ts">
import {ref} from 'vue'
import {api,message,notify} from '../api'
import Icon from '../components/Icon.vue'
const files=ref<File[]>([]),results=ref<{name:string;message:string;ok:boolean}[]>([]),busy=ref(false),error=ref(''),input=ref<HTMLInputElement|null>(null)
function selectFiles(event:Event){files.value=Array.from((event.target as HTMLInputElement).files||[]);results.value=[];error.value=files.value.length>20?'一次最多导入 20 个文件，请重新选择。':''}
function escapeText(text:string){return text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c))}
async function importBatch(){if(!files.value.length||files.value.length>20||busy.value)return;busy.value=true;results.value=[];error.value='';try{for(const file of files.value){try{const payload=new FormData();payload.append('file',file);const {data}=await api.post('/member/import',payload);const body=String(data.text||'').split(/\n\s*\n/).map(p=>`<p>${escapeText(p).replace(/\n/g,'<br>')}</p>`).join('');await api.post('/member/works',{title:file.name.replace(/\.(docx|pdf|txt)$/i,'').slice(0,100)||'未命名稿件',genre:'其他',excerpt:'',body,cover:'',tagIds:[],publish:false});results.value.push({name:file.name,message:'已保存为草稿',ok:true})}catch(e){results.value.push({name:file.name,message:message(e),ok:false})}}notify(`导入完成：${results.value.filter(r=>r.ok).length} 篇已保存为草稿`)}finally{busy.value=false;files.value=[];if(input.value)input.value.value=''}}
</script>
<template><header class="admin-page-heading"><div><p class="admin-kicker">BATCH IMPORT</p><h1>批量导入</h1><p>将散落在文档里的文字，收进编辑部的书桌。</p></div><RouterLink to="/account" class="button secondary small">前往我的书桌 <Icon name="ArrowUpRight" :size="14"/></RouterLink></header><div class="admin-info"><Icon name="FileText" :size="20"/><p>支持 TXT、DOCX 与文字型 PDF，一次最多 20 个文件。解析后的文章保存为草稿，请在“我的书桌”中校对署名、正文与体裁后发布。</p></div><div class="admin-settings-grid"><form class="admin-surface admin-form" @submit.prevent="importBatch"><div class="admin-section-title"><div><h2>选择稿件文件</h2><p>文件名将作为初始文章标题。</p></div></div><label class="admin-upload-zone"><Icon name="Upload" :size="32"/><strong>选择要导入的文档</strong><span>TXT / DOCX / PDF · 最多 20 个</span><input ref="input" type="file" accept=".txt,.docx,.pdf" multiple :disabled="busy" @change="selectFiles"/></label><p v-if="error" class="error-message" role="alert">{{error}}</p><ul v-if="files.length" class="admin-file-list"><li v-for="(f,index) in files" :key="index"><Icon name="FileText" :size="15"/><span>{{f.name}}</span><small>{{Math.ceil(f.size/1024)}} KB</small></li></ul><footer class="admin-form-actions"><span v-if="busy" role="status">已处理 {{results.length}} / {{files.length}}</span><button class="button" :disabled="busy||!files.length||files.length>20">{{busy?'正在导入…':`导入并保存草稿${files.length?`（${files.length}）`:''}`}}</button></footer></form><aside class="admin-help"><Icon name="BookOpen" :size="24"/><h3>导入之后</h3><ol><li>打开“我的书桌”找到草稿。</li><li>校对内容，补充署名和标签。</li><li>预览排版，确认后发布。</li></ol><p>扫描版 PDF 不支持文字提取，请使用文字型文档。</p></aside></div><section v-if="results.length" class="admin-section" aria-live="polite"><div class="admin-section-title"><div><h2>导入结果</h2><p>成功 {{results.filter(r=>r.ok).length}} 篇 · 失败 {{results.filter(r=>!r.ok).length}} 篇</p></div></div><div class="admin-surface"><div v-for="(r,index) in results" :key="index" class="admin-import-result"><Icon :name="r.ok?'Check':'X'" :size="17"/><strong>{{r.name}}</strong><span :class="{'admin-danger-link':!r.ok}">{{r.message}}</span></div></div></section></template>
